public async Task<string?> LoadAttemptAsync(string examId, string userId, CancellationToken cancellationToken)
{
    var key = $"attempt:{examId}:{userId}";
    return await _redis.GetDatabase().StringGetAsync(key);
}

public List<string> NaiveFilter(IEnumerable<string> rows, string prefix)
{
    return rows.Where(r => r.StartsWith(prefix)).Select(r => r.ToUpperInvariant()).ToList();
}
